        match (LanguagePrimitives.EnumToValue (LanguagePrimitives.EnumOfValue<int, InfilModel> model)) with
        | 0 | 1 ->
            lg.[0] <- v6.[0]
            lg.[1] <- v6.[1]
            lg.[2] <- v6.[2]
            ()
        | 2 | 3 ->
            lg.[0] <- v6.[0]
            lg.[1] <- v6.[1]
            lg.[2] <- v6.[2]
            lg.[3] <- v6.[4]
            lg.[4] <- v6.[3]
            ()
        | 4 ->
            lg.[0] <- v6.[0]
            lg.[1] <- v6.[2]
            lg.[2] <- v6.[3]
            lg.[3] <- v6.[5]
            lg.[4] <- v6.[1]
            lg.[5] <- v6.[4]
            ()
        | _ ->
            ()
    static member infilFromLegacy_SWMMEngine (model: int, lg: Cpp.Ptr<float>, v6: Cpp.Ptr<float>) : unit =
