    static member convertSnapshotToDisplay_SWMMEngine (s: SimulationSnapshot, du: ucf_DisplayUnits) : unit =
        let lam'600 = FN32(fun (v: Cpp.Vec<float>) (f: float) ->
            if (f = 1.0) then
                ()
            else
                let mutable __r1 : Cpp.Vec<float> = v
                let mutable __i2 : int64 = 0L
                let mutable __i2_n : int64 = (int64 __r1.n)
                while (__i2 < __i2_n) do
                    let x = &__r1.a.[int __i2]
                    x <- (x * f)
                    __i2 <- (__i2 + 1L)
                ()
            )
        let mutable scale : FN32 = lam'600
        scale.Invoke(s.subcatch.rainfall, du.rainfall)
        scale.Invoke(s.subcatch.snow_depth, du.raindepth)
        scale.Invoke(s.subcatch.evap, du.evaprate)
        scale.Invoke(s.subcatch.infil, du.rainfall)
        scale.Invoke(s.subcatch.runoff, du.flow)
        scale.Invoke(s.subcatch.gw_flow, du.flow)
        scale.Invoke(s.subcatch.gw_elev, du.length)
        scale.Invoke(s.nodes.depth, du.length)
        scale.Invoke(s.nodes.head, du.length)
        scale.Invoke(s.nodes.volume, du.volume)
        scale.Invoke(s.nodes.lateral_inflow, du.flow)
        scale.Invoke(s.nodes.total_inflow, du.flow)
        scale.Invoke(s.nodes.overflow, du.flow)
        scale.Invoke(s.links.flow, du.flow)
        scale.Invoke(s.links.depth, du.length)
        scale.Invoke(s.links.velocity, du.length)
        scale.Invoke(s.links.volume, du.volume)
        if s.has_subcatchments then
            s.sys_temperature <- du.temperature(s.sys_temperature)
        s.sys_rainfall <- (s.sys_rainfall * du.rainfall)
        s.sys_snow_depth <- (s.sys_snow_depth * du.raindepth)
        s.sys_infil <- (s.sys_infil * du.rainfall)
        s.sys_runoff <- (s.sys_runoff * du.flow)
        s.sys_dw_inflow <- (s.sys_dw_inflow * du.flow)
        s.sys_gw_inflow <- (s.sys_gw_inflow * du.flow)
        s.sys_ii_inflow <- (s.sys_ii_inflow * du.flow)
        s.sys_ext_inflow <- (s.sys_ext_inflow * du.flow)
        s.sys_flooding <- (s.sys_flooding * du.flow)
        s.sys_outflow <- (s.sys_outflow * du.flow)
        s.sys_storage <- (s.sys_storage * du.volume)
        s.sys_evap <- (s.sys_evap * du.evaprate)
        s.sys_pet <- (s.sys_pet * du.evaprate)

