    member this.refreshReportedSpecies () : unit =
        this.reported_species_names.clear()
        let mutable p : int = 0
        while (p < this.n_pollutants()) do
            this.reported_species_names.push_back(this.pollutant_names.name_of(p).Clone())
            p <- (p + 1)
        if this.options.water_age then
            this.reported_species_names.push_back(Cpp.Str(Cpp.R.Lit("__WATER_AGE__")))
        if this.options.heat_transport then
            this.reported_species_names.push_back(Cpp.Str(Cpp.R.Lit("__TEMPERATURE__")))
        this.reactions.reported_species.clear()
        let mutable m : int = 0
        while (m < this.reactions.n_species()) do
            if ((not (this.reactions.report_enabled.empty())) && (not (not ((int this.reactions.report_enabled.[(uint64 m)]) = 0)))) then
                ()
            else
                this.reactions.reported_species.push_back(m)
                this.reported_species_names.push_back(this.reactions.species_name.[(uint64 m)].Clone())
            m <- (m + 1)
    member this.n_reported_species () : int =
        (int (this.reported_species_names.size()))
    member this.logControlAction (e: SimulationContext_ControlLogEntry) : unit =
        if (this.control_log.size() >= SimulationContext__S.I.kMaxControlLog) then
            this.control_log_dropped <- (this.control_log_dropped + 1UL)
            ()
        else
            this.control_log.push_back(e.Clone())
    static member updateMaxStats (arr: Cpp.Ptr<SimulationContext_MaxStats>, obj_type: int, idx: int, value: float) : unit =
        let mutable candidate : SimulationContext_MaxStats = SimulationContext_MaxStats()
        candidate.obj_type <- obj_type
        candidate.index <- idx
        candidate.value <- value
        let mutable k : int = 0
        while (k < SimulationContext__S.I.MAX_STATS) do
            if (System.Math.Abs(candidate.value) > System.Math.Abs(arr.[k].value)) then
                let mutable tmp : SimulationContext_MaxStats = SimulationContext_MaxStats.New_rMaxStats(arr.[k])
                arr.[k].Assign(candidate)
                candidate.Assign(tmp)
            k <- (k + 1)
    member this.finalize_max_stats () : unit =
        let mutable k : int = 0
        while (k < SimulationContext__S.I.MAX_STATS) do
            Cpp.Ptr<SimulationContext_MaxStats>(this.max_courant_crit, 0L).[k].MoveFrom((let o'767 = SimulationContext_MaxStats() in o'767.obj_type <- 0; o'767.index <- (-1); o'767.value <- (-1.0); o'767))
            Cpp.Ptr<SimulationContext_MaxStats>(this.max_flow_turns, 0L).[k].MoveFrom((let o'768 = SimulationContext_MaxStats() in o'768.obj_type <- 1; o'768.index <- (-1); o'768.value <- (-1.0); o'768))
            Cpp.Ptr<SimulationContext_MaxStats>(this.max_non_converged, 0L).[k].MoveFrom((let o'769 = SimulationContext_MaxStats() in o'769.obj_type <- 0; o'769.index <- (-1); o'769.value <- 0.0; o'769))
            k <- (k + 1)
        let mutable rpt_steps : int64 = this.routing_stats.report_steps
        if (rpt_steps > 2L) then
            let mutable z : float = (100.0 / (0.6666666666666666 * (float (rpt_steps - 2L))))
            let mutable j : int = 0
            while (j < this.n_links()) do
                let mutable x : float = ((float this.links.stat_flow_turns.[(uint64 j)]) * z)
                SimulationContext.updateMaxStats(Cpp.Ptr<SimulationContext_MaxStats>(this.max_flow_turns, 0L), 1, j, x)
                j <- (j + 1)
        let mutable step_count : int64 = this.routing_stats.n_steps
        let mutable dw : bool = (LanguagePrimitives.EnumToValue this.options.routing_model = LanguagePrimitives.EnumToValue RoutingModel.DYNWAVE)
        if dw then
            let mutable j_2 : int = 0
            while (j_2 < this.n_nodes()) do
                SimulationContext.updateMaxStats(Cpp.Ptr<SimulationContext_MaxStats>(this.max_non_converged, 0L), 0, j_2, ((float this.nodes.stat_non_converged_count.[(uint64 j_2)]) / (float step_count)))
                j_2 <- (j_2 + 1)
        if (((not dw) || (this.options.variable_step = 0.0)) || (step_count = 0L)) then
            ()
        else
            let mutable inv_steps : float = (1.0 / (float step_count))
            let mutable j_3 : int = 0
            while (j_3 < this.n_nodes()) do
                let mutable x_2 : float = (this.nodes.stat_time_courant_critical.[(uint64 j_3)] * inv_steps)
                SimulationContext.updateMaxStats(Cpp.Ptr<SimulationContext_MaxStats>(this.max_courant_crit, 0L), 0, j_3, (100.0 * x_2))
                j_3 <- (j_3 + 1)
            let mutable j_4 : int = 0
            while (j_4 < this.n_links()) do
                let mutable x_3 : float = (this.links.stat_time_courant_critical.[(uint64 j_4)] * inv_steps)
                SimulationContext.updateMaxStats(Cpp.Ptr<SimulationContext_MaxStats>(this.max_courant_crit, 0L), 1, j_4, (100.0 * x_3))
                j_4 <- (j_4 + 1)
    member this.reset () : unit =
        this.outfall_exports.MoveFrom((let o'770 = SimulationContext_OutfallExports() in o'770.water_m3 <- Cpp.Vec<float>(); o'770.reverse_m3 <- Cpp.Vec<float>(); o'770.heat_j <- Cpp.Vec<float>(); o'770.pollutant_amounts <- Cpp.Vec<float>(); o'770))
        this.runtime_coupling_used <- false
