type FlowUnits =
    | CFS = 0
    | GPM = 1
    | MGD = 2
    | CMS = 3
    | LPS = 4
    | MLD = 5

type RoutingModel =
    | STEADY = 0
    | KINWAVE = 1
    | DYNWAVE = 2
    | FV = 3

type QualitySolverKind =
    | LEGACY = 0
    | EULERIAN_ARD = 1
    | LAGRANGIAN = 2

type InfiltrationModel =
    | HORTON = 0
    | MOD_HORTON = 1
    | GREEN_AMPT = 2
    | MOD_GREEN_AMPT = 3
    | CURVE_NUMBER = 4

type RunoffModel =
    | NONE = 0
