    member this.resize_total_load (n_sc: int, n_poll: int) : unit =
        this.total_load_n_pollutants <- n_poll
        this.total_load.assign(((uint64 n_sc) * (uint64 n_poll)), 0.0)
    member this.count () : int =
        (int (this.area.size()))
    member this.resize (n: int) : unit =
        let mutable un : uint64 = (uint64 n)
        this.outlet_node.assign(un, (-1))
        this.outlet_subcatch.assign(un, (-1))
        this.outlet_name.resize(un)
        this.snowpack_name.resize(un)
        this.gage_name.resize(un)
        this.gage.assign(un, (-1))
        this.area.assign(un, 0.0)
        this.width.assign(un, 0.0)
        this.slope.assign(un, 0.0)
        this.curb_length.assign(un, 0.0)
        this.rain_scale_factor.assign(un, 1.0)
        this.snow_scale_factor.assign(un, 1.0)
        this.frac_imperv.assign(un, 0.0)
