[<AbstractClass; Sealed>]
type F_dynwave =
    static member isOpenShape_DynamicWave (shape: XsectShape) : bool =
        match (LanguagePrimitives.EnumToValue shape) with
        | 25s | 3s | 4s | 5s | 6s | 7s | 21s | 24s ->
            true
        | _ ->
            false
    static member conveyArea_DynamicWave (a: float, a_full: float) : float =
        let mutable a = a
        let mutable a_full = a_full
        (if (a > a_full) then a_full else a)
    static member buildXSP_DynamicWave (ctx: SimulationContext, uk: uint64) : XSectParams =
        let mutable links : LinkData = ctx.links
        let mutable xs : XSectParams = XSectParams()
        let mutable ls : XsectShape = links.xsect_shape.[uk]
        xs.``type`` <- F_link.translateShape(ls)
        xs.y_full <- links.xsect_y_full.[uk]
        xs.a_full <- links.xsect_a_full.[uk]
        xs.w_max <- links.xsect_w_max.[uk]
        xs.yw_max <- links.xsect_yw_max.[uk]
        xs.r_full <- links.xsect_r_full.[uk]
        xs.s_full <- links.xsect_s_full.[uk]
        xs.s_max <- links.xsect_s_max.[uk]
        xs.y_bot <- links.xsect_y_bot.[uk]
        xs.a_bot <- links.xsect_a_bot.[uk]
        xs.s_bot <- links.xsect_s_bot.[uk]
        xs.r_bot <- links.xsect_r_bot.[uk]
        if (((LanguagePrimitives.EnumToValue ls = LanguagePrimitives.EnumToValue XsectShape.IRREGULAR) || (LanguagePrimitives.EnumToValue ls = LanguagePrimitives.EnumToValue XsectShape.CUSTOM)) || (LanguagePrimitives.EnumToValue ls = LanguagePrimitives.EnumToValue XsectShape.STREET_XSECT)) then
            let mutable ci : int = links.xsect_curve.[uk]
            if ((ci >= 0) && ((uint64 ci) < ctx.transect_tables.size())) then
                let mutable td : transect_TransectData = ctx.transect_tables.[(uint64 ci)]
                xs.transect <- ci
                xs.area_tbl <- Cpp.Ptr<float>(td.area_tbl, 0L)
                xs.hrad_tbl <- Cpp.Ptr<float>(td.hrad_tbl, 0L)
                xs.width_tbl <- Cpp.Ptr<float>(td.width_tbl, 0L)
                xs.area_lut <- td.area_lut
                xs.transect_tbl_size <- F_transect__S.I.N_TRANSECT_TBL
        XSectParams.MoveNew(xs)
    static member chamberPipeVolumeChange_DynamicWave (ctx: SimulationContext, node: int, link: int, area1: float, area2: float, iteration_depth: Cpp.Ptr<float>) : float =
        let mutable area1 = area1
        let mutable area2 = area2
        let mutable n1 : int = ctx.links.node1.[(uint64 link)]
        let mutable n2 : int = ctx.links.node2.[(uint64 link)]
        let mutable other : int = (if (n1 = node) then n2 else n1)
        if (LanguagePrimitives.EnumToValue ctx.nodes.``type``.[(uint64 other)] = LanguagePrimitives.EnumToValue NodeType.OUTFALL) then
            (ctx.links.volume.[(uint64 link)] - ctx.links.old_volume.[(uint64 link)])
        else
            let mutable old1 : float = F_dynwave.chamberEndArea_DynamicWave(ctx, link, (ctx.nodes.old_depth.[(uint64 n1)] - ctx.links.offset1.[(uint64 link)]))
            let mutable old2 : float = F_dynwave.chamberEndArea_DynamicWave(ctx, link, (ctx.nodes.old_depth.[(uint64 n2)] - ctx.links.offset2.[(uint64 link)]))
            if (ctx.nodes.storage_area.[(uint64 n1)] > 0.0) then
                area1 <- F_dynwave.chamberEndArea_DynamicWave(ctx, link, (iteration_depth.[n1] - ctx.links.offset1.[(uint64 link)]))
            if (ctx.nodes.storage_area.[(uint64 n2)] > 0.0) then
                area2 <- F_dynwave.chamberEndArea_DynamicWave(ctx, link, (iteration_depth.[n2] - ctx.links.offset2.[(uint64 link)]))
            let mutable before : float = (if ((old1 + old2) > 0.0) then (old1 / (old1 + old2)) else 0.5)
            let mutable after : float = (if ((area1 + area2) > 0.0) then (area1 / (area1 + area2)) else 0.5)
            if (not (n1 = node)) then
                before <- (1.0 - before)
                after <- (1.0 - after)
            ((after * ctx.links.volume.[(uint64 link)]) - (before * ctx.links.old_volume.[(uint64 link)]))
    static member chamberEndArea_DynamicWave (ctx: SimulationContext, link: int, depth: float) : float =
        let mutable xs : XSectParams = F_dynwave.buildXSP_DynamicWave(ctx, (uint64 link))
        if (depth <= 0.0) then
            0.0
        else
            if (depth < xs.y_full) then
                F_xsect.getAofY(xs, depth)
            else
                let mutable slot : float = 0.0
                if ((ctx.options.surcharge_method = 1) && (not (F_dynwave.isOpenShape_DynamicWave(ctx.links.xsect_shape.[(uint64 link)])))) then
                    let mutable ratio : float = (depth / xs.y_full)
                    slot <- (if (ratio > 1.78) then (0.01 * xs.w_max) else ((xs.w_max * 0.5423) * Cpp.LibM.exp((-(Cpp.LibM.pow(ratio, 2.4))))))
                (xs.a_full + ((depth - xs.y_full) * slot))
    static member computeYnorm_DynamicWave (xs: XSectParams, beta: float, q_max: float, q: float) : float =
        let mutable q = q
        if ((beta <= 0.0) || (q <= 0.0)) then
            0.0
        else
            if ((q_max > 0.0) && (q > q_max)) then
                q <- q_max
            let mutable s : float = (q / beta)
            let mutable a : float = F_xsect.getAofS(xs, s)
            F_xsect.getYofA(xs, a)

