                        this.soa_.btm_area.[uk] <- (this.soa_.btm_area.[uk] / (ucf_len * ucf_len))
                        this.soa_.bank_max_area.[uk] <- (this.soa_.bank_max_area.[uk] / (ucf_len * ucf_len))
                        this.soa_.bank_min_depth.[uk] <- (this.soa_.bank_min_depth.[uk] / ucf_len)
