[<AbstractClass; Sealed>]
type F_forcemain =
    static member getEquivN (model: forcemain_FrictionModel, r_bot: float, y_full: float, slope: float, n_raw: float) : float =
        let mutable ret' = false
        let mutable rv' = 0.0
        if ((slope <= 0.0) || (y_full <= 0.0)) then
            n_raw
        else
            match (LanguagePrimitives.EnumToValue model) with
            | 0 ->
                rv' <- ((1.067 / r_bot) * Cpp.LibM.pow((y_full / slope), 0.04))
                ret' <- true
            | 1 ->
                let mutable hrad : float = (y_full / 4.0)
                let mutable f : float = F_forcemain.getFricFactor(r_bot, hrad, 1000000000000.0)
                rv' <- (System.Math.Sqrt((f / 185.0)) * Cpp.LibM.pow(y_full, 0.16666666666666666))
                ret' <- true
            | _ -> ()
            if ret' then rv'
            else
                n_raw
    static member getRoughFactor (model: forcemain_FrictionModel, r_bot: float, length_factor: float) : float =
        let mutable length_factor = length_factor
        let mutable ret' = false
        let mutable rv' = 0.0
        if (length_factor <= 0.0) then
            length_factor <- 1.0
        let mutable G : float = 32.2
        match (LanguagePrimitives.EnumToValue model) with
        | 0 ->
            let mutable denom : float = ((1.318 * r_bot) * Cpp.LibM.pow(length_factor, 0.54))
            rv' <- (if (denom > 0.0) then (G / Cpp.LibM.pow(denom, 1.852)) else 0.0)
            ret' <- true
        | 1 ->
            rv' <- (1.0 / (8.0 * length_factor))
            ret' <- true
        | _ -> ()
        if ret' then rv'
        else
            0.0
    static member getFricFactor (r_bot: float, hrad: float, re: float) : float =
        let mutable re = re
        if (hrad <= 0.0) then
            0.0
        else
            let mutable f : float = 0.0
            if (re < 10.0) then
                re <- 10.0
            if (re <= 2000.0) then
                f <- (64.0 / re)
            elif (re < 4000.0) then
                f <- F_forcemain.getFricFactor(r_bot, hrad, 4000.0)
                f <- (0.032 + (((f - 0.032) * (re - 2000.0)) / 2000.0))
            else
                f <- ((r_bot / 3.7) / (4.0 * hrad))
                if (re < 10000000000.0) then
                    f <- (f + (5.74 / Cpp.LibM.pow(re, 0.9)))
                f <- Cpp.LibM.log10(f)
                f <- ((0.25 / f) / f)
            f

