    member this.initNodeFlows (ctx: SimulationContext, dt: float, evap_rate: float) : unit =
        let mutable nodes : NodeData = ctx.nodes
        let mutable n : int = ctx.n_nodes()
        let mutable i : int = 0
        while (i < n) do
            let mutable ui : uint64 = (uint64 i)
            let mutable loss_rate : float = 0.0
            if (LanguagePrimitives.EnumToValue nodes.``type``.[ui] = LanguagePrimitives.EnumToValue NodeType.STORAGE) then
                let mutable sr : int = ctx.node_subtypes.storage_row(i)
                let mutable st : StorageData = ctx.node_subtypes.storages
                let mutable sru : uint64 = (uint64 sr)
                let mutable evap_frac : float = (if (sr >= 0) then st.evap_frac.[sru] else 0.0)
                let mutable seep_rate : float = (if (sr >= 0) then st.seep_rate.[sru] else 0.0)
                let mutable stor_evap_rate : float = (evap_rate * evap_frac)
                if ((sr >= 0) && (not (st.lid_state.[sru].cells.empty()))) then
                    let mutable state : LidNodeState = st.lid_state.[sru]
                    let mutable potential : float = ((evap_rate * evap_frac) * state.cells.front().area)
                    let mutable area : float = F_node.getSurfArea(nodes, i, nodes.depth.[ui], ctx.tables, F_ucf.getUnitSystem((LanguagePrimitives.EnumToValue ctx.options.flow_units)), ctx.node_subtypes)
                    stor_evap_rate <- (if (area > 0.0) then (Cpp.M.max(0.0, (potential - (state.evap_volume / dt))) / area) else 0.0)
                    if state.richards then
                        stor_evap_rate <- 0.0
                let mutable exfil_cfs : float = (if (sr >= 0) then st.exfil_rate.[sru] else 0.0)
                if (((stor_evap_rate > 0.0) || (seep_rate > 0.0)) || (exfil_cfs > 0.0)) then
                    let mutable depth : float = nodes.depth.[ui]
                    let mutable area_2 : float = F_node.getSurfArea(nodes, i, depth, ctx.tables, F_ucf.getUnitSystem((LanguagePrimitives.EnumToValue ctx.options.flow_units)), ctx.node_subtypes)
                    let mutable evap_cfs : float = stor_evap_rate
                    if (nodes.volume.[ui] > F_constants__S.I.FUDGE) then
                        evap_cfs <- (area_2 * stor_evap_rate)
                    let mutable total_loss : float = ((evap_cfs + exfil_cfs) * dt)
                    if ((total_loss > nodes.volume.[ui]) && (total_loss > 0.0)) then
                        let mutable ratio : float = (nodes.volume.[ui] / total_loss)
                        evap_cfs <- (evap_cfs * ratio)
                        exfil_cfs <- (exfil_cfs * ratio)
                    if (sr >= 0) then
                        st.evap_loss.[sru] <- (evap_cfs * dt)
                        st.exfil_loss.[sru] <- (exfil_cfs * dt)
                    loss_rate <- (evap_cfs + exfil_cfs)
                elif (sr >= 0) then
                    st.evap_loss.[sru] <- 0.0
                    st.exfil_loss.[sru] <- 0.0
            nodes.losses.[ui] <- loss_rate
            nodes.inflow.[ui] <- nodes.lat_flow.[ui]
            nodes.outflow.[ui] <- nodes.losses.[ui]
            let mutable full_vol : float = (if (LanguagePrimitives.EnumToValue ctx.options.routing_model = LanguagePrimitives.EnumToValue RoutingModel.FV) then nodes.full_volume.[ui] else nodes.rpt_full_volume.[ui])
            if ((nodes.volume.[ui] > full_vol) && (dt > 0.0)) then
                nodes.overflow.[ui] <- ((nodes.volume.[ui] - full_vol) / dt)
            else
                nodes.overflow.[ui] <- 0.0
            i <- (i + 1)
    member this.computeConduitLosses (ctx: SimulationContext, dt: float, evap_rate: float) : unit =
        let mutable links : LinkData = ctx.links
        let mutable n : int = ctx.n_links()
        let mutable j : int = 0
        while (j < n) do
            let mutable uj : uint64 = (uint64 j)
            if (not (LanguagePrimitives.EnumToValue links.``type``.[uj] = LanguagePrimitives.EnumToValue LinkType.CONDUIT)) then
                ()
            else
                let mutable CD : ConduitData = ctx.link_subtypes.conduits
                let mutable ucr : uint64 = (uint64 (ctx.link_subtypes.conduit_row(j)))
                let mutable depth : float = (0.5 * (links.old_depth.[uj] + links.depth.[uj]))
                let mutable evap_loss : float = 0.0
                let mutable seep_loss : float = 0.0
                if (depth > F_constants__S.I.FUDGE) then
                    let mutable length : float = CD.true_length.[ucr]
                    if (length <= 0.0) then
                        length <- CD.length.[ucr]
                    if (length <= 0.0) then
                        length <- CD.mod_length.[ucr]
                    let mutable batch_shape : int = links.xsect_batch_shape.[uj]
                    let mutable gw_two_way : bool = ((not (CD.gw_coupled.empty())) && (not ((int CD.gw_coupled.[ucr]) = 0)))
                    let mutable k_seep : float = (if gw_two_way then CD.gw_kc.[ucr] else CD.seep_rate.[ucr])
                    let mutable wantEvap : bool = (F_xsect.isOpen(batch_shape) && (evap_rate > 0.0))
                    let mutable wantSeep : bool = (k_seep > 0.0)
                    if (wantEvap || wantSeep) then
                        let mutable xs : XSectParams = XSectParams()
                        xs.``type`` <- batch_shape
                        xs.y_full <- links.xsect_y_full.[uj]
                        xs.a_full <- links.xsect_a_full.[uj]
                        xs.w_max <- links.xsect_w_max.[uj]
                        xs.yw_max <- links.xsect_yw_max.[uj]
                        xs.r_full <- links.xsect_r_full.[uj]
                        xs.s_full <- links.xsect_s_full.[uj]
                        xs.s_max <- links.xsect_s_max.[uj]
                        xs.y_bot <- links.xsect_y_bot.[uj]
                        xs.a_bot <- links.xsect_a_bot.[uj]
                        xs.s_bot <- links.xsect_s_bot.[uj]
                        xs.r_bot <- links.xsect_r_bot.[uj]
                        if (((batch_shape = 22) || (batch_shape = 23)) || (batch_shape = 25)) then
                            let mutable ci : int = links.xsect_curve.[uj]
                            if ((ci >= 0) && ((uint64 ci) < ctx.transect_tables.size())) then
                                let mutable td : transect_TransectData = ctx.transect_tables.[(uint64 ci)]
                                xs.transect <- ci
                                xs.area_tbl <- Cpp.Ptr<float>(td.area_tbl, 0L)
                                xs.hrad_tbl <- Cpp.Ptr<float>(td.hrad_tbl, 0L)
                                xs.width_tbl <- Cpp.Ptr<float>(td.width_tbl, 0L)
                                xs.area_lut <- td.area_lut
                                xs.transect_tbl_size <- F_transect__S.I.N_TRANSECT_TBL
                        if wantEvap then
                            let mutable top_width : float = 0.0
                            if ((batch_shape = 22) || (batch_shape = 23)) then
                                top_width <- (if (xs.y_full > 0.0) then (xs.w_max * Cpp.M.min((depth / xs.y_full), 1.0)) else 0.0)
                            else
                                top_width <- F_xsect.getWofY(xs, depth)
                            evap_loss <- ((top_width * length) * evap_rate)
                        if wantSeep then
                            let mutable d_seep : float = depth
                            let mutable width : float = 0.0
                            if (batch_shape = 3) then
                                width <- xs.w_max
                            else
                                if (d_seep >= xs.yw_max) then
                                    d_seep <- xs.yw_max
                                width <- F_xsect.getWofY(xs, d_seep)
                            seep_loss <- ((k_seep * width) * length)
                            seep_loss <- (seep_loss * ctx.climate_state.infil_factor)
                            if gw_two_way then
                                seep_loss <- (seep_loss * F_hydraulics.aquiferSeepFactor(depth, CD.gw_head_rel.[ucr], CD.gw_dc.[ucr]))
                                seep_loss <- F_hydraulics.capAquiferGain(seep_loss, CD.gw_gain_max.[ucr])
                    let mutable total : float = (evap_loss + Cpp.M.max(seep_loss, 0.0))
                    if ((total > 0.0) && ((LanguagePrimitives.EnumToValue this.model_ = LanguagePrimitives.EnumToValue RouteModel.DYNWAVE) || (LanguagePrimitives.EnumToValue this.model_ = LanguagePrimitives.EnumToValue RouteModel.FV))) then
                        let mutable q_avail : float = (links.volume.[uj] / (dt * (float CD.barrels.[ucr])))
                        if ((total > q_avail) && (q_avail >= 0.0)) then
                            let mutable ratio : float = (q_avail / total)
                            evap_loss <- (evap_loss * ratio)
                            if (seep_loss > 0.0) then
                                seep_loss <- (seep_loss * ratio)
                F_hydraulics.applySeepageForcing(ctx, uj, &seep_loss)
                CD.evap_loss_rate.[ucr] <- evap_loss
                CD.seep_loss_rate.[ucr] <- seep_loss
            j <- (j + 1)
    member this.refreshFvBoundaryFlows (ctx: SimulationContext, t_elapsed: float, eval_structures: FN3) : unit =
        let mutable impl : fv_ExplicitFvSolver = (this.fv_solver_ :?> fv_ExplicitFvSolver)
        if (not (not (obj.ReferenceEquals((box impl), null)))) then
            ()
        else
            this.accumulateStructureFlows(ctx, t_elapsed)
            let mutable nn : int = ctx.n_nodes()
            let mutable n : int = 0
            while (n < nn) do
                let mutable un : uint64 = (uint64 n)
                if ((int this.fv_mesh_.node_kind.[un]) = 1) then
                    ()
                else
                    let mutable depth : float = (this.fv_state_.node_head.[un] - this.fv_mesh_.node_invert.[un])
                    ctx.nodes.depth.[un] <- Cpp.M.max(0.0, depth)
                    ctx.nodes.head.[un] <- this.fv_state_.node_head.[un]
                n <- (n + 1)
            F_outfall.setAllOutfallDepths(ctx, t_elapsed)
            let mutable n_2 : int = 0
            while (n_2 < nn) do
                let mutable un_2 : uint64 = (uint64 n_2)
                if (not (LanguagePrimitives.EnumToValue ctx.nodes.``type``.[un_2] = LanguagePrimitives.EnumToValue NodeType.OUTFALL)) then
                    ()
                else
                    this.fv_fixed_head_.[un_2] <- (ctx.nodes.invert_elev.[un_2] + ctx.nodes.depth.[un_2])
                n_2 <- (n_2 + 1)
            eval_structures.Invoke()
    member this.accumulateStructureFlows (ctx: SimulationContext, t_now: float) : unit =
        let mutable span : float = (t_now - this.fv_struct_t_prev_)
        if (span <= 0.0) then
            ()
        else
