    override this.initialize (mesh: fv_NetworkMeshData, state: fv_NetworkStateData, opts: fv_FvOptions) : unit =
        this.mesh_ <- mesh
        this.state_ <- state
        this.opts_.Assign(opts)
        let mutable nf : uint64 = (uint64 (mesh.n_faces()))
        let mutable nc : uint64 = (uint64 (mesh.n_cells()))
        let mutable nn : uint64 = (uint64 (mesh.n_nodes()))
        let mutable ns : uint64 = (uint64 (Cpp.M.max(0, state.n_species)))
        if this.water_tracking_ then
            this.water_.resize(nf, mesh.struct_link.size(), nc, nn)
            this.save_water_.Assign(this.water_)
            this.rk_water_.Assign(this.water_)
        if (mesh.node_sur_depth.size() < nn) then
            mesh.node_sur_depth.resize(nn, 0.0)
        if (mesh.node_can_pond.size() < nn) then
            mesh.node_can_pond.resize(nn, 0uy)
        mesh.deriveFaceGeom()
        if (mesh.face_gate.size() < nf) then
            mesh.face_gate.resize(nf, 0uy)
        if (mesh.face_culvert.size() < nf) then
            mesh.face_culvert.resize(nf, (-1))
        this.f_mass_.assign(nf, 0.0)
        this.f_mom_.assign(nf, 0.0)
        this.f_sstar_.assign(nf, 0.0)
        this.f_corr_l_.assign(nf, 0.0)
        this.f_corr_r_.assign(nf, 0.0)
        this.f_phi_l_.assign((ns * nf), 0.0)
        this.f_phi_r_.assign((ns * nf), 0.0)
        this.f_phi_flux_.assign((ns * nf), 0.0)
        this.f_state_l_.assign(nf, fv_kernels_FaceState())
        this.f_state_r_.assign(nf, fv_kernels_FaceState())
        this.f_flux_.assign(nf, fv_kernels_FaceFlux())
        this.hllc_ <- (LanguagePrimitives.EnumToValue opts.riemann = LanguagePrimitives.EnumToValue fv_RiemannSolver.HLLC)
        this.cell_slope_.assign(nc, 0.0)
        this.cell_eta_slope_.assign(nc, 0.0)
        this.cell_u_slope_.assign(nc, 0.0)
        this.cell_ho2_.assign(nc, 0y)
        this.cell_eta_.assign(nc, 0.0)
        this.cell_u_.assign(nc, 0.0)
        this.cell_ah_.assign(nc, 0.0)
        this.cell_t_.assign(nc, 0.0)
        this.cell_i1_.assign(nc, 0.0)
        this.cell_q_int_.assign(nc, 0.0)
        this.uf_grad_.assign((if (not (opts.unsteady_friction = 0)) then nc else 0UL), 0.0)
        this.tpa_ <- (opts.pressure_closure = 1)
        let mutable mw : Cpp.CPtr = Cpp.R.getenv(Cpp.R.Lit("OPENSWMM_FV_MIXED_WAVE"))
        this.mixed_wave_ <- (not ((not mw.IsNull) && ((int (sbyte mw.[0])) = 48)))
        this.mw_rh_ <- this.mixed_wave_
        let mutable d1 : Cpp.CPtr = Cpp.R.getenv(Cpp.R.Lit("OPENSWMM_FV_DEG1"))
        this.deg1_guard_slot_ <- (not ((not d1.IsNull) && ((int (sbyte d1.[0])) = 49)))
        let mutable cp : Cpp.CPtr = Cpp.R.getenv(Cpp.R.Lit("OPENSWMM_FV_CENSUS_PASS"))
        this.census_pass_far_ <- (not ((not cp.IsNull) && ((int (sbyte cp.[0])) = 48)))
        let mutable lf : Cpp.CPtr = Cpp.R.getenv(Cpp.R.Lit("OPENSWMM_FV_LTS_FIT"))
        this.lts_fit_ <- ((not lf.IsNull) && ((int (sbyte lf.[0])) = 49))
        let mutable cf : Cpp.CPtr = Cpp.R.getenv(Cpp.R.Lit("OPENSWMM_FV_CFL"))
        if (not cf.IsNull) then
            let mutable v : float = Cpp.R.atof(cf)
            if ((v > 0.0) && (v <= 1.0)) then
                this.opts_.cfl <- v
        if this.tpa_ then
            state.cell_tpa.assign(nc, 0uy)
            this.tpa_scratch_.assign(nc, 0uy)
        else
            state.cell_tpa.clear()
            this.tpa_scratch_.clear()
        this.withdrawal_rates_.assign(nn, 0.0)
        this.unmet_withdrawal_.assign(nn, 0.0)
        this.save_unmet_.Assign(this.unmet_withdrawal_)
        this.rk_unmet_.Assign(this.unmet_withdrawal_)
        this.node_exch_.assign(nn, 0.0)
        this.node_in_.assign(nn, 0.0)
        this.node_out_.assign(nn, 0.0)
        this.flood_vol_.assign(nn, 0.0)
        this.node_qdummy_.assign((if mesh.struct_is_dummy.empty() then 0UL else nn), 0.0)
        this.dummy_vol_.assign(mesh.struct_link.size(), 0.0)
        this.inlet_control_.assign((uint64 (mesh.n_conduits())), 0uy)
        this.cell_tier_.assign(nc, 0uy)
        this.node_tier_.assign(nn, 0uy)
        this.face_tier_.assign(nf, 0uy)
        this.relax_beta_.assign(nf, 0.0)
        this.acc_a_.clear()
        this.acc_q_.clear()
        this.acc_nvol_.clear()
        this.cells_by_tier_.clear()
        this.faces_by_tier_.clear()
        this.nodes_by_tier_.clear()
        this.lts_tiers_ <- 1
        System.Array.Fill<int64>(this.tier_occupancy_, 0L)
        this.cell_active_.assign(nc, 1y)
        this.active_faces_.clear()
        this.lists_valid_ <- false
        this.since_rebuild_ <- 0
        this.census_count_ <- 0
        this.dt_cache_ <- 0.0
        this.dt_census_ <- 0.0
        this.lts_valid_ <- false
        this.lts_countdown_ <- 0
        this.lts_dt0_ <- 0.0
        this.total_steps_ <- 0L
        this.total_flux_ <- 0L
        this.min_h_ <- 0.0
        this.sim_time_ <- 0.0
        this.active_sum_ <- 0.0
        this.active_min_ <- (-1.0)
        this.active_max_ <- (-1.0)
        this.active_n_ <- 0L
        this.n_macro_cycles_ <- 0L
        this.n_macro_rejected_ <- 0L
        this.state_clean_ <- false
        this.acc_dirty_ <- false
        this.refreshDepths()
        this.refreshNodeAreas()
        this.node_alg_.assign(nn, 0uy)
        this.node_carry_.assign(nn, 0.0)
        this.node_vfull_.assign(nn, 0.0)
        this.node_pass_static_.assign(nn, 0uy)
        this.node_pass_.assign(nn, 0uy)
        this.node_pub_static_.assign(nn, 0uy)
        this.node_pub_.assign(nn, 0uy)
        let mutable un : uint64 = 0UL
        while (un < nn) do
            this.node_vfull_.[un] <- this.nodeVolumeFromDepth((int un), this.mesh_.node_full_depth.[un])
            this.node_alg_.[un] <- (byte (if ((((int this.mesh_.node_kind.[un]) = 0) && (this.mesh_.node_vol_off.[un] < 0)) && (this.mesh_.node_face_ptr.[(un + 1UL)] > this.mesh_.node_face_ptr.[un])) then 1 else 0))
            let mutable clean : bool = (not ((int this.node_alg_.[un]) = 0))
            if clean then
                let mutable p : int = this.mesh_.node_face_ptr.[un]
                while (p < this.mesh_.node_face_ptr.[(un + 1UL)]) do
                    let mutable uf : uint64 = (uint64 this.mesh_.node_face_idx.[(uint64 p)])
                    if ((this.mesh_.face_culvert.[uf] >= 0) || (not ((int this.mesh_.face_gate.[uf]) = 0))) then
                        clean <- false
                    p <- (p + 1)
            this.node_pub_static_.[un] <- (byte (if clean then 1 else 0))
            if (clean && ((this.mesh_.node_face_ptr.[(un + 1UL)] - this.mesh_.node_face_ptr.[un]) = 2)) then
                this.node_pass_static_.[un] <- 1uy
            un <- (un + 1UL)
        this.face_a_rim_.assign(nf, System.Double.PositiveInfinity)
        this.face_lat_spill_.assign(nf, 0.0)
        let mutable un_2 : uint64 = 0UL
        while (un_2 < nn) do
            if (not (not ((int this.node_pass_static_.[un_2]) = 0))) then
                ()
            else
                let mutable full : float = this.mesh_.node_full_depth.[un_2]
                if (not (full > 0.0)) then
                    ()
                else
                    let mutable rim : float = ((this.mesh_.node_invert.[un_2] + full) + (if (not ((int this.mesh_.node_can_pond.[un_2]) = 0)) then 0.0 else this.mesh_.node_sur_depth.[un_2]))
                    let mutable p_2 : int = this.mesh_.node_face_ptr.[un_2]
                    while (p_2 < this.mesh_.node_face_ptr.[(un_2 + 1UL)]) do
                        let mutable uf_2 : uint64 = (uint64 this.mesh_.node_face_idx.[(uint64 p_2)])
                        let mutable c : int = (if (this.mesh_.face_cl.[uf_2] >= 0) then this.mesh_.face_cl.[uf_2] else this.mesh_.face_cr.[uf_2])
                        if (c < 0) then
                            ()
                        else
                            let mutable uc : uint64 = (uint64 c)
                            let mutable g : fv_FvGeometry = this.mesh_.geom.[(uint64 this.mesh_.cell_geom.[uc])]
                            if (not ((int g.is_open) = 0)) then
                                ()
                            else
                                let mutable h_rim : float = (rim - this.mesh_.cell_zb.[uc])
                                this.face_a_rim_.[uf_2] <- (if (h_rim > 0.0) then F_fv_kernels.areaOfDepth(g, h_rim) else 0.0)
                        p_2 <- (p_2 + 1)
            un_2 <- (un_2 + 1UL)
        let mutable n : uint64 = 0UL
        while (n < nn) do
            if ((((int mesh.node_kind.[n]) = 1) || ((int mesh.node_kind.[n]) = 3)) || this.algebraicActive((int n))) then
                state.node_volume.[n] <- 0.0
            else
                state.node_volume.[n] <- this.nodeVolumeFromDepth((int n), Cpp.M.max(0.0, (state.node_head.[n] - mesh.node_invert.[n])))
            n <- (n + 1UL)
    override this.advance (t_current: float, t_target: float, forcing: fv_FvStepForcing) : float =
        if (((not this.pressure_candidate_) || (not (not (obj.ReferenceEquals((box this.mesh_), null))))) || (t_target <= t_current)) then
            this.advanceImpl(t_current, t_target, forcing)
        else
            this.validatePressureCandidate(forcing)
            this.pressure_rejections_ <- 0L
            let mutable state : fv_NetworkStateData = this.state_.Clone()
            let mutable water : fv_AcceptedWaterVolumes = this.water_.Clone()
            let mutable unmet : Cpp.Vec<float> = this.unmet_withdrawal_.Clone()
            let mutable carry : Cpp.Vec<float> = this.node_carry_.Clone()
            let mutable exchange : Cpp.Vec<float> = this.node_exch_.Clone()
            let mutable incoming : Cpp.Vec<float> = this.node_in_.Clone()
            let mutable outgoing : Cpp.Vec<float> = this.node_out_.Clone()
            let mutable flood : Cpp.Vec<float> = this.flood_vol_.Clone()
            let mutable qint : Cpp.Vec<float> = this.cell_q_int_.Clone()
            let mutable dummy : Cpp.Vec<float> = this.dummy_vol_.Clone()
            let mutable inlet : Cpp.Vec<byte> = this.inlet_control_.Clone()
            let mutable published : Cpp.Vec<byte> = this.node_pub_.Clone()
            let mutable last : float = this.last_h_
            let mutable minimum : float = this.min_h_
            let mutable cached : float = this.dt_cache_
            let mutable simulated : float = this.sim_time_
            let mutable suggested : float = this.suggested_h_
            let mutable total : int64 = this.total_steps_
            let mutable previous_steps : int64 = this.last_nsteps_
            try
                let mutable reached : float = this.advanceImpl(t_current, t_target, forcing)
                if (not (reached = t_target)) then
                    raise ((Cpp.RuntimeError((Cpp.Str.op_Implicit(Cpp.R.Lit("Nonlinear pressure-storage candidate did not finish its routing window.")))) :> System.Exception))
                else
                    reached
            with
            | __ex1 ->
                Cpp.Dbg.Caught(__ex1)
                this.state_.Assign(state)
                this.water_.Assign(water)
                this.unmet_withdrawal_.Assign(unmet)
                this.node_carry_.Assign(carry)
                this.node_exch_.Assign(exchange)
                this.node_in_.Assign(incoming)
                this.node_out_.Assign(outgoing)
                this.flood_vol_.Assign(flood)
                this.cell_q_int_.Assign(qint)
                this.dummy_vol_.Assign(dummy)
                this.inlet_control_.Assign(inlet)
                this.node_pub_.Assign(published)
                this.last_h_ <- last
                this.min_h_ <- minimum
                this.dt_cache_ <- cached
                this.sim_time_ <- simulated
                this.suggested_h_ <- suggested
                this.total_steps_ <- total
                this.last_nsteps_ <- previous_steps
                Cpp.Algo.fill<float>(this.face_lat_spill_.``begin``(), this.face_lat_spill_.``end``(), 0.0)
                this.refreshDepths()
                this.state_.Assign(state)
                this.state_clean_ <- false
                this.lists_valid_ <- false
                this.census_count_ <- 0
                reraise ()
    override this.run_stats () : fv_INetworkSolver_RunStats =
        let mutable s : fv_INetworkSolver_RunStats = fv_INetworkSolver_RunStats()
        s.nsteps <- this.total_steps_
        s.nflux <- this.total_flux_
        s.last_h <- this.last_h_
        s.min_h <- this.min_h_
        s.avg_h <- (if (this.total_steps_ > 0L) then (this.sim_time_ / (float this.total_steps_)) else 0.0)
        if (this.active_n_ > 0L) then
            s.active_frac_mean <- (this.active_sum_ / (float this.active_n_))
            s.active_frac_min <- this.active_min_
            s.active_frac_max <- this.active_max_
        s.n_tiers <- Cpp.M.min(this.lts_tiers_, F_fv__S.I.kMaxLtsTiers)
        let mutable k : int = 0
        while (k < s.n_tiers) do
            Cpp.Ptr<int64>(s.tier_cells, 0L).[k] <- this.tier_occupancy_.[int (uint64 k)]
            k <- (k + 1)
        s.dt_argmin_pressurized <- this.dt_argmin_pressurized_
        s.dt_argmin_band <- this.dt_argmin_band_
        s.dt_argmin_free <- this.dt_argmin_free_
        s.dt_argmin_node <- this.dt_argmin_node_
        s.n_macro_cycles <- this.n_macro_cycles_
        s.n_macro_rejected <- this.n_macro_rejected_
        fv_INetworkSolver_RunStats.MoveNew(s)
    member this.nodeVolumeFromDepth (node: int, depth: float) : float =
        let mutable un : uint64 = (uint64 node)
        if (depth <= 0.0) then
            0.0
        else
            let mutable full : float = this.mesh_.node_full_depth.[un]
            if (((not ((int this.mesh_.node_can_pond.[un]) = 0)) && (full > 0.0)) && (depth > full)) then
                (this.nodeVolumeFromDepth(node, full) + ((depth - full) * this.mesh_.node_ponded_area.[un]))
            else
                let mutable off : int = this.mesh_.node_vol_off.[un]
                if (off < 0) then
                    (this.state_.node_surf_area.[un] * depth)
                else
                    let mutable dmax : float = this.mesh_.node_vol_dmax.[un]
                    let mutable n : int = F_fv__S.I.kNodeVolSamples
                    let mutable vmax : float = this.mesh_.node_vol_tbl.[(uint64 ((off + n) - 1))]
                    if (depth >= dmax) then
                        (vmax + (this.mesh_.node_vol_atop.[un] * (depth - dmax)))
                    else
                        let mutable dd : float = (dmax / (float (n - 1)))
                        let mutable i : int = Cpp.Conv.D2I((depth / dd))
                        if (i > (n - 2)) then
                            i <- (n - 2)
                        if (i < 0) then
                            i <- 0
                        let mutable t : float = ((depth - ((float i) * dd)) / dd)
                        let mutable v0 : float = this.mesh_.node_vol_tbl.[(uint64 (off + i))]
                        let mutable v1 : float = this.mesh_.node_vol_tbl.[(uint64 ((off + i) + 1))]
                        (v0 + ((v1 - v0) * t))
    member this.advanceImpl (t_current: float, t_target: float, forcing: fv_FvStepForcing) : float =
        if ((not (not (obj.ReferenceEquals((box this.mesh_), null)))) || (t_target <= t_current)) then
            t_target
        else
            this.forcing_ <- forcing
            Cpp.Algo.fill<float>(this.unmet_withdrawal_.``begin``(), this.unmet_withdrawal_.``end``(), 0.0)
            if this.water_tracking_ then
                this.water_.clear()
            Cpp.Algo.fill<float>(this.node_exch_.``begin``(), this.node_exch_.``end``(), 0.0)
            Cpp.Algo.fill<float>(this.node_in_.``begin``(), this.node_in_.``end``(), 0.0)
            Cpp.Algo.fill<float>(this.node_out_.``begin``(), this.node_out_.``end``(), 0.0)
            Cpp.Algo.fill<float>(this.flood_vol_.``begin``(), this.flood_vol_.``end``(), 0.0)
            Cpp.Algo.fill<byte>(this.inlet_control_.``begin``(), this.inlet_control_.``end``(), 0uy)
            Cpp.Algo.fill<float>(this.cell_q_int_.``begin``(), this.cell_q_int_.``end``(), 0.0)
            Cpp.Algo.fill<float>(this.dummy_vol_.``begin``(), this.dummy_vol_.``end``(), 0.0)
            if (not this.state_clean_) then
                this.refreshDepths()
            let mutable n : int = 0
            while (n < this.mesh_.n_nodes()) do
                let mutable un : uint64 = (uint64 n)
                if ((int this.mesh_.node_kind.[un]) = 1) then
                    ()
                else
                    if ((not (this.node_alg_.empty())) && this.algebraicActive(n)) then
                        ()
                    else
                        this.state_.node_volume.[un] <- this.nodeVolumeFromDepth(n, Cpp.M.max(0.0, (this.state_.node_head.[un] - this.mesh_.node_invert.[un])))
                n <- (n + 1)
            this.refreshStructFlows(forcing)
            let mutable t : float = t_current
            let mutable steps : int64 = 0L
            this.lists_valid_ <- false
            this.census_count_ <- 0
            let mutable brk'1 = false
            let mutable cnt'1 = false
            while not brk'1 && (t < t_target) do
                cnt'1 <- false
                if (((steps > 0L) && (not (obj.ReferenceEquals(forcing.refresh, Unchecked.defaultof<FN20>)))) && (LanguagePrimitives.EnumToValue this.opts_.structure_coupling = LanguagePrimitives.EnumToValue fv_StructureCoupling.SUBSTEP)) then
                    let mutable _pt_cb : perf_GatedTimer = perf_GatedTimer.New_rd(&F_perf__S.I.sec_fv_bndcallback)
                    forcing.refresh.Invoke(forcing.refresh_user, (t - t_current))
                    this.refreshStructFlows(forcing)
                if ((not this.lists_valid_) || (this.since_rebuild_ >= fv_ExplicitFvSolver__S.I.kRebuildInterval)) then
                    this.rebuildActiveLists()
                    this.census_count_ <- 0
                let mutable press : bool = this.anyPressurizedCell()
                if (press && this.lts_valid_) then
                    this.settleAccumulators()
                    this.lts_valid_ <- false
                if ((not press) && this.ltsEligible()) then
                    let mutable now : float = (if (this.lts_valid_ && (this.lts_tiers_ > 1)) then this.censusDt(false) else 0.0)
                    let mutable stiffness_moved : bool = ((this.lts_valid_ && (this.lts_tiers_ > 1)) && ((now < (0.9 * this.lts_dt0_)) || (now > (2.0 * this.lts_dt0_))))
                    let mutable retiered : bool = false
                    if (((not this.lts_valid_) || (this.lts_countdown_ <= 0)) || stiffness_moved) then
                        retiered <- true
                        this.settleAccumulators()
                        this.lts_tiers_ <- this.assignTiers(&this.lts_dt0_, 0)
                        this.lts_valid_ <- true
                        this.lts_countdown_ <- fv_ExplicitFvSolver__S.I.kRetierEveryCycles
                        this.census_count_ <- 0
                    let mutable K : int = this.lts_tiers_
                    let mutable dt0 : float = this.lts_dt0_
                    this.lts_countdown_ <- (this.lts_countdown_ - 1)
                    let mutable nsub : int = (1 <<< (K - 1))
                    let mutable span : float = ((float nsub) * dt0)
                    if ((K > 1) && (span <= (t_target - t))) then
                        if (this.opts_.order < 2) then
                            this.reconstructState()
                        this.saveState()
                        this.runMacroCycle(dt0, nsub, forcing)
                        if (this.censusDt(false) < (fv_ExplicitFvSolver__S.I.kStepAcceptRatio * dt0)) then
                            this.n_macro_rejected_ <- (this.n_macro_rejected_ + 1L)
                            F_perf.count(perf_FvCounter.n_fv_macro_rejected, 1L)
                            this.restoreState()
                            this.lts_valid_ <- false
