    static member MoveNew (s: fv_ExplicitFvSolver) : fv_ExplicitFvSolver =
        let mutable o : fv_ExplicitFvSolver = fv_ExplicitFvSolver(Cpp.Raw.V)
        o.MoveFrom(s)
        o
    override this.last_num_steps () : int64 =
        this.last_nsteps_
    override this.suggested_step () : float =
        this.suggested_h_
    override this.divergence (d: fv_INetworkSolver_Divergence) : bool =
        if (this.div_link_ < 0) then
            false
        else
            d.link <- this.div_link_
            d.value <- this.div_value_
            d.what <- this.div_what_
            true
    member this.setConduitStepSink (fn: FN19, user: obj) : unit =
        this.step_sink_ <- fn
        this.step_sink_user_ <- user
    member this.trackAcceptedWater (enabled: bool) : unit =
        this.water_tracking_ <- enabled
        if (enabled && (not (obj.ReferenceEquals((box this.mesh_), null)))) then
            this.water_.resize((uint64 (this.mesh_.n_faces())), this.mesh_.struct_link.size(), (uint64 (this.mesh_.n_cells())), (uint64 (this.mesh_.n_nodes())))
        else
            this.water_.MoveFrom((let o'2421 = fv_AcceptedWaterVolumes() in o'2421.face_forward <- Cpp.Vec<float>(); o'2421.face_reverse <- Cpp.Vec<float>(); o'2421.structure_forward <- Cpp.Vec<float>(); o'2421.structure_reverse <- Cpp.Vec<float>(); o'2421.cell_lateral <- Cpp.Vec<float>(); o'2421.cell_loss <- Cpp.Vec<float>(); o'2421.node_deficit <- Cpp.Vec<float>(); o'2421.face_lateral_left <- Cpp.Vec<float>(); o'2421.face_lateral_right <- Cpp.Vec<float>(); o'2421.face_spill <- Cpp.Vec<float>(); o'2421))
        this.save_water_.Assign(this.water_)
        this.rk_water_.Assign(this.water_)
    member this.acceptedWater () : fv_AcceptedWaterVolumes =
        this.water_
    member this.requireConservativeNodeBalance (enabled: bool) : unit =
        this.conservative_node_balance_ <- enabled
    member this.withdrawalRates__v () : Cpp.Vec<float> =
        this.withdrawal_rates_
    member this.withdrawalRates__v_t2 () : Cpp.Vec<float> =
        this.withdrawal_rates_
    member this.unmetWithdrawalVolumes () : Cpp.Vec<float> =
        this.unmet_withdrawal_
    member this.node_continuity_carry () : Cpp.Vec<float> =
        this.node_carry_
    member this.node_inflow_volume () : Cpp.Vec<float> =
        this.node_in_
    member this.node_outflow_volume () : Cpp.Vec<float> =
        this.node_out_
    member this.bookDivertedLateral (un: uint64, dt: float, forcing: fv_FvStepForcing) : unit =
        if ((this.node_lat_div_.empty() || (not (not ((int this.node_lat_div_.[un]) = 0)))) || (not (not forcing.node_lateral.IsNull))) then
            ()
        else
            let mutable lat : float = forcing.node_lateral.[un]
            if (lat > 0.0) then
                this.node_out_.[un] <- (this.node_out_.[un] + (lat * dt))
    member this.inlet_control () : Cpp.Vec<byte> =
        this.inlet_control_
    member this.node_flood_volume () : Cpp.Vec<float> =
        this.flood_vol_
    member this.dummy_volume () : Cpp.Vec<float> =
        this.dummy_vol_
    member this.node_publish_stage () : Cpp.Vec<byte> =
        this.node_pub_
    member this.cell_flow_integral () : Cpp.Vec<float> =
        this.cell_q_int_
    member this.nodeLateral (forcing: fv_FvStepForcing, un: uint64) : float =
        if ((not (this.node_lat_div_.empty())) && (not ((int this.node_lat_div_.[un]) = 0))) then
            0.0
        else
            (if (not forcing.node_lateral.IsNull) then forcing.node_lateral.[un] else 0.0)
    member this.algebraicActive (n: int) : bool =
        let mutable un : uint64 = (uint64 n)
        if (not (not ((int this.node_alg_.[un]) = 0))) then
            false
        else
            if ((not ((int this.mesh_.node_can_pond.[un]) = 0)) && (this.state_.node_volume.[un] > this.node_vfull_.[un])) then
                false
            else
                true
    member this.incidentPressurized (un: uint64) : bool =
        let mutable ret' = false
        let mutable rv' = false
        let mutable p : int = this.mesh_.node_face_ptr.[un]
        while not ret' && (p < this.mesh_.node_face_ptr.[(un + 1UL)]) do
            let mutable uf : uint64 = (uint64 this.mesh_.node_face_idx.[(uint64 p)])
            let mutable c : int = (if (this.mesh_.face_cl.[uf] >= 0) then this.mesh_.face_cl.[uf] else this.mesh_.face_cr.[uf])
            if (c < 0) then
                ()
            else
                let mutable uc : uint64 = (uint64 c)
                if this.tpaCell(uc) then
                    rv' <- true
                    ret' <- true
                else
                    let mutable g : fv_FvGeometry = this.mesh_.geom.[(uint64 this.mesh_.cell_geom.[uc])]
                    if ((not (not ((int g.is_open) = 0))) && (this.state_.cell_h.[uc] >= g.y_crown)) then
                        rv' <- true
                        ret' <- true
            if not (ret') then
                p <- (p + 1)
        if ret' then rv'
        else
            false
    member this.nodeQDummy (un: uint64) : float =
